<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';admin_required();$pdo=db();
if(is_post()){try{verify_csrf();if((string)setting('sms_marketing_enabled','1')!=='1')throw new RuntimeException('پیامک گروهی از تنظیمات سیستم غیرفعال است.');$action=scalar_string($_POST['action']??'create');$id=max(0,scalar_int($_POST['id']??0));
    if($action==='create'){$id=create_sms_campaign($pdo,scalar_string($_POST['title']??''),scalar_string($_POST['audience']??'all'),max(0,scalar_int($_POST['template_id']??0)),scalar_string($_POST['parameter_name']??''),scalar_string($_POST['parameter_value']??''),(int)admin_user()['id']);flash('success','کمپین و فهرست گیرندگان ساخته شد. پیش از شروع تعداد مخاطبان را بررسی کنید.');}
    elseif($action==='start'){if(!sms_enabled())throw new RuntimeException('ابتدا SMS.ir را از بخش پیامک فعال کنید.');$pdo->prepare("UPDATE sms_campaigns SET status='running',started_at=COALESCE(started_at,NOW()),completed_at=NULL WHERE id=? AND status IN ('draft','paused','completed')")->execute([$id]);flash('success','کمپین فعال شد.');}
    elseif($action==='pause'){$pdo->prepare("UPDATE sms_campaigns SET status='paused' WHERE id=? AND status='running'")->execute([$id]);flash('success','کمپین متوقف شد.');}
    elseif($action==='process'){$result=process_sms_campaign($id,20);flash('success',fa_number($result['processed']).' گیرنده پردازش شد.');}
    elseif($action==='retry'){$pdo->prepare("UPDATE sms_campaign_recipients SET status='pending',error_message=NULL,processed_at=NULL WHERE campaign_id=? AND status IN ('failed','skipped')")->execute([$id]);$pdo->prepare("UPDATE sms_campaigns SET status='paused',sent_count=(SELECT COUNT(*) FROM sms_campaign_recipients WHERE campaign_id=? AND status='sent'),failed_count=0,completed_at=NULL WHERE id=?")->execute([$id,$id]);flash('success','گیرندگان ناموفق یا آزمایشی برای تلاش دوباره آماده شدند.');}
}catch(Throwable $e){flash('error',$e->getMessage());}redirect(app_url('admin/sms-campaigns.php'));}
$rows=$pdo->query("SELECT c.*,(SELECT COUNT(*) FROM sms_campaign_recipients r WHERE r.campaign_id=c.id AND r.status='skipped') skipped_count FROM sms_campaigns c ORDER BY c.id DESC LIMIT 200")->fetchAll();$eligible=(int)$pdo->query('SELECT COUNT(*) FROM customers WHERE is_active=1 AND marketing_sms_enabled=1')->fetchColumn();$cronCommand=central_cron_cli_command('/usr/local/bin/php');$adminPage='campaigns';$adminTitle='پیامک گروهی مشتریان';require __DIR__.'/partials/header.php';?>
<div class="admin-title"><h1>پیامک گروهی مشتریان</h1><span><?=fa_number($eligible)?> مشتری مجاز به دریافت</span></div><div class="flash warning">ارسال فقط برای مشتریانی انجام می‌شود که دریافت پیامک فروشگاهی را در حساب خود فعال نگه داشته‌اند. قالب باید در SMS.ir تأیید شده باشد.</div><div class="card"><strong>پردازش با Cron مرکزی</strong><div class="codebox" dir="ltr"><?=e($cronCommand)?></div><small>فقط همین Cron مرکزی را هر ۱۰ دقیقه اجرا کنید؛ کمپین‌های فعال در هر اجرا پردازش می‌شوند. در حالت Sandbox پیام واقعی ارسال نمی‌شود. <a href="<?=e(app_url('admin/system-health.php'))?>">مشاهده سلامت Cron</a></small></div>
<form method="post" class="card"><?=csrf_field()?><input type="hidden" name="action" value="create"><h2>کمپین جدید</h2><div class="form-grid"><div class="field"><label>عنوان داخلی</label><input name="title" maxlength="160" required></div><div class="field"><label>مخاطبان</label><select name="audience"><option value="all">همه مشتریان ثبت‌نام‌شده</option><option value="buyers">مشتریان دارای سفارش</option><option value="non_buyers">ثبت‌نام‌شده بدون سفارش</option></select></div><div class="field"><label>شناسه قالب SMS.ir</label><input type="number" name="template_id" min="1" required></div><div class="field"><label>نام پارامتر قالب</label><input name="parameter_name" dir="ltr" pattern="[A-Za-z0-9_]{1,50}" maxlength="50" placeholder="TEXT" required></div><div class="field full"><label>مقدار پارامتر</label><input name="parameter_value" maxlength="100" required><small>هر کمپین یک پارامتر ثابت در قالب Verify می‌فرستد؛ حداکثر ۱۰۰ کاراکتر.</small></div></div><button class="btn btn-primary">ساخت پیش‌نویس</button></form>
<div class="card table-wrap"><table><thead><tr><th>عنوان</th><th>مخاطب</th><th>پیشرفت</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=e($row['title'])?></strong><br>قالب <?=fa_number($row['template_id'])?></td><td><?=e(['all'=>'همه','buyers'=>'خریداران','non_buyers'=>'بدون سفارش'][$row['audience']]??$row['audience'])?></td><td><?=fa_number($row['sent_count'])?> موفق / <?=fa_number($row['failed_count'])?> ناموفق / <?=fa_number($row['skipped_count'])?> آزمایشی / <?=fa_number($row['total_count'])?> کل</td><td><?=e($row['status'])?></td><td><div class="admin-actions"><?php if(in_array($row['status'],['draft','paused'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="start"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="btn btn-primary">شروع</button></form><?php endif?><?php if($row['status']==='running'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="process"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="btn btn-secondary">ارسال ۲۰ مورد</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="pause"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="btn btn-secondary">توقف</button></form><?php endif?><?php if((int)$row['failed_count']>0||(int)$row['skipped_count']>0):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="retry"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="btn btn-secondary">آماده‌سازی ارسال مجدد</button></form><?php endif?></div></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="5">کمپینی ساخته نشده است.</td></tr><?php endif?></tbody></table></div>
<?php require __DIR__.'/partials/footer.php';
